    const [, forceRender] = useReducer((x: number) => x + 1, 0)

    useEffect(() => {
        if (!ttEditor) {
            return
        }
        const dom = ttEditor.view.dom

        const onMouseOver = (event: MouseEvent): void => {
            if (openMenu) {
                return
