            const cell = event.target instanceof Element ? event.target.closest('td, th') : null
            // Tables rendered inside notebook nodes are not editable document tables
            const isDocumentCell = cell instanceof HTMLTableCellElement && !cell.closest('.NotebookNode')
            setHoveredCell(isDocumentCell ? cell : null)
        }

        const onMouseLeave = (event: MouseEvent): void => {
            if (!openMenu && !isWithinHandle(event.relatedTarget)) {
                setHoveredCell(null)
            }
